package glitch

import data.glitch_lib

deferred_work_pattern := "(?i)\\b(TODO|FIXME|LATER2?|TBD|PENDING|INCOMPLETE|BUG|HACK|KLUDGE?|XXX|WORKAROUND|BROKEN)\\b"

security_sensitive_pattern := "(?i)(temporary|\\btemp\\b|insecure|not.?secure|disabled?|bypassed?|allow.?all|unrestricted|hard.?coded|placeholder|dummy|remove.?before|delete.?before|vulnerable|weakness|dangerous|risky|change.?this|replace.?this|update.?this|not.?for.?prod|testing.?only|dev.?only)"

comment_is_suspicious(content) {
    regex.match(deferred_work_pattern, content)
}

comment_is_suspicious(content) {
    regex.match(security_sensitive_pattern, content)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    comment := parent.comments[_]
    comment_is_suspicious(comment.content)

    result := {
        "type": "sec_susp_comm",
        "element": comment,
        "path": parent.path,
        "description": "Suspicious comment detected - May indicate unresolved security issues, deferred security configurations, or bypassed security controls. (CWE-546)"
    }
}
